79. fn build_layout(main_area: Rect) -> SplashLayout {
80.     let frame_width = main_area.width.saturating_sub(8).clamp(64, 92);
81.     let frame_height = main_area.height.saturating_sub(2).clamp(17, 24);
82.     let frame_x = main_area.x + (main_area.width.saturating_sub(frame_width)) / 2;
83.     let frame_y = main_area.y + (main_area.height.saturating_sub(frame_height)) / 2;
84.     let frame = Rect::new(frame_x, frame_y, frame_width, frame_height);
85.     let inner = Rect::new(
86.         frame.x.saturating_add(3),
87.         frame.y.saturating_add(1),
88.         frame.width.saturating_sub(6),
89.         frame.height.saturating_sub(2),
90.     );
91.     let sections = Layout::default()
92.         .direction(Direction::Vertical)
93.         .constraints([
94.             Constraint::Length(if frame.width >= WIDE_TITLE_WIDTH {
95.                 9
96.             } else {
97.                 5
98.             }),
99.             Constraint::Length(1),
100.             Constraint::Length(6),
101.             Constraint::Length(2),
102.         ])
103.         .split(inner);
104. 
105.     SplashLayout {
106.         frame,
107.         title: sections[0],
108.         menu: sections[2],
109.         footer: sections[3],
110.     }
111. }
