379. fn render_compact_menu(
380.     frame: &mut Frame,
381.     area: Rect,
382.     app_state: &AppState,
383.     palette: SplashPalette,
384. ) {
385.     let content = Layout::default()
386.         .direction(Direction::Vertical)
387.         .constraints([
388.             Constraint::Length(2),
389.             Constraint::Length(1),
390.             Constraint::Length(4),
391.             Constraint::Length(1),
392.         ])
393.         .split(Rect::new(
394.             area.x + area.width.saturating_sub(34) / 2,
395.             area.y + area.height.saturating_sub(10) / 2,
396.             area.width.min(34),
397.             area.height.min(10),
398.         ));
399. 
400.     frame.render_widget(
401.         Clear,
402.         Rect::new(content[0].x, content[0].y, content[0].width, 10),
403.     );
404.     frame.render_widget(
405.         Paragraph::new(vec![
406.             Line::from(Span::styled(
407.                 "FARSPACE",
408.                 Style::default()
409.                     .fg(palette.title_primary)
410.                     .add_modifier(Modifier::BOLD),
411.             )),
412.             Line::from(Span::styled(
413.                 TAGLINE,
414.                 Style::default()
415.                     .fg(palette.accent)
416.                     .add_modifier(Modifier::BOLD),
417.             )),
418.         ])
419.         .alignment(Alignment::Center)
420.         .style(Style::default().bg(palette.void_bg)),
421.         content[0],
422.     );
423.     frame.render_widget(
424.         Paragraph::new(build_menu_lines(app_state, palette))
425.             .alignment(Alignment::Center)
426.             .style(Style::default().bg(palette.void_bg)),
427.         content[2],
428.     );
429.     render_footer_line(frame, content[3], palette, FOOTER_HINT_COMPACT, false);
430. }
