432. fn render_dashboard(frame: &mut Frame, area: Rect, app_state: &AppState, palette: SplashPalette) {
433.     let layout = build_layout(area);
434.     frame.render_widget(
435.         Block::default().style(Style::default().bg(palette.void_bg)),
436.         layout.frame,
437.     );
438.     render_gradient_frame(frame, layout.frame, palette);
439. 
440.     let title = Paragraph::new(build_title_lines(layout.frame.width, palette))
441.         .alignment(Alignment::Center)
442.         .style(Style::default().bg(palette.void_bg))
443.         .wrap(Wrap { trim: false });
444.     frame.render_widget(title, layout.title);
445. 
446.     let menu = Paragraph::new(build_menu_lines(app_state, palette))
447.         .alignment(Alignment::Center)
448.         .style(Style::default().bg(palette.void_bg));
449.     frame.render_widget(menu, layout.menu);
450. 
451.     render_footer_line(frame, layout.footer, palette, FOOTER_HINT, true);
452. }
