454. fn build_info() -> String {
455.     match option_env!("FARSPACE_BUILD_TAG") {
456.         Some(tag) if !tag.is_empty() => format!("v{}-{tag}", env!("CARGO_PKG_VERSION")),
457.         _ => format!("v{}", env!("CARGO_PKG_VERSION")),
458.     }
459. }
