482.     fn cell_char(buf: &Buffer, x: u16, y: u16) -> char {
483.         buf.cell((x, y))
484.             .and_then(|c| c.symbol().chars().next())
485.             .unwrap_or(' ')
486.     }
487. 
488.     fn render_to_buffer(width: u16, height: u16) -> Buffer {
489.         let backend = TestBackend::new(width, height);
490.         let mut terminal = Terminal::new(backend).unwrap();
491.         terminal
492.             .draw(|frame| render_menu(frame, frame.area(), &AppState::default()))
493.             .unwrap();
494.         terminal.backend().buffer().clone()
495.     }
496. 
497.     fn buffer_text(buf: &Buffer, width: u16, height: u16) -> String {
498.         (0..height)
499.             .flat_map(|y| (0..width).map(move |x| cell_char(buf, x, y)))
500.             .collect()
501.     }
502. 
