163.             let selected = app_state.menu_cursor % MENU_ACTION_COUNT == index;
164.             let marker = if selected { "▶ " } else { "  " };
165.             let marker_style = if selected {
166.                 Style::default()
167.                     .fg(palette.accent)
168.                     .bg(lerp_rgb(palette.void_bg, palette.nebula_b, 0.18))
169.                     .add_modifier(Modifier::BOLD)
170.             } else {
171.                 Style::default().fg(palette.text_muted)
172.             };
173.             let label_style = if selected {
174.                 Style::default()
175.                     .fg(palette.title_primary)
176.                     .bg(lerp_rgb(palette.void_bg, palette.nebula_b, 0.18))
177.                     .add_modifier(Modifier::BOLD)
178.             } else {
179.                 Style::default().fg(Theme::fg())
180.             };
