             ("[Enter]", "Confirm"),
             ("[Esc]", "Back"),
             ("[?]", "Help"),
         ],
         Screen::NewGameSetup => vec![
             ("[j/k]", "Select Field"),
             ("[h/l]", "Change Value"),
             ("[Enter]", "Use Field"),
             ("[S]", "Start"),
             ("[Esc]", "Back"),
             ("[?]", "Help"),
         ],
         Screen::SectorOverview => vec![
             ("[hjkl/←↓↑→]", "Move"),
             ("[Enter]", "Sector Map"),
             ("[L]", "Toggle Lanes"),
             ("[r]", "Research"),
             ("[D]", "Diplomacy"),
             ("[O/V]", "Overview/Victory"),
             ("[E/T]", "End Turn"),
             ("[?]", "Help"),
             ("[:]", "Command"),
             ("[Q]", "Quit"),
         ],
         Screen::SectorMap => vec![
             ("[hjkl/←↓↑→]", "Move"),
             ("[Enter]", "System View"),
             ("[c]", "Colony"),
             ("[r]", "Research"),
             ("[D]", "Diplomacy"),
             ("[O/V]", "Overview/Victory"),
             ("[S]", "Scout"),
             ("[M]", "Move Fleet"),
             ("[E/T]", "End Turn"),
             ("[?]", "Help"),
             ("[:]", "Command"),
             ("[Esc]", "Galaxy"),
             ("[Q]", "Quit"),
         ],
         Screen::System => vec![
             ("[j/k]", "Select Planet"),
             ("[Enter]", "Open Selected/First Player Colony"),
             ("[S]", "Survey"),
             ("[C]", "Colonize Selected"),
             ("[I]", "Invade Selected"),
             ("[f]", "Cycle Fleet Focus"),
             ("[R]", "Next Fleet Role"),
             ("[F]", "Next Fleet Formation"),
             ("[O/V]", "Overview/Victory"),
             ("[e/t]", "End Turn"),
             ("[?]", "Help"),
             ("[Esc]", "Back"),
         ],
         Screen::Colony => vec![
             ("[j/k]", "Select"),
             ("[Enter]", "Queue"),
             ("[R]", "Set Rally"),
             ("[X]", "Clear Rally"),
             ("[O/V]", "Overview/Victory"),
             ("[e/t]", "End Turn"),
             ("[?]", "Help"),
             ("[Esc]", "Back"),
         ],
         Screen::EmpireOverview => vec![
             ("[j/k]", "Select"),
             ("[s]", "Sort"),
             ("[/]", "Filter"),
             ("[Enter]", "Colony"),
             ("[S]", "System"),
             ("[e/t]", "End Turn"),
             ("[Esc]", "Back"),
         ],
         Screen::Research => vec![
             ("[j/k]", "Tree Cursor"),
             ("[Tab]", "Domain"),
             ("[[]", "Era"),
             ("[]]", "Status"),
             ("[/]", "Search"),
             ("[Enter]", "Set Active Tech"),
             ("[a]", "Queue"),
             ("[x]", "Remove"),
             ("[u/d]", "Reorder"),
             ("[c]", "Clear Queue"),
             ("[O/V]", "Overview/Victory"),
             ("[e/t]", "End Turn"),
             ("[?]", "Help"),
             ("[Esc]", "Back"),
         ],
         Screen::Diplomacy => vec![
             ("[e/t/Enter]", "End Turn"),
             ("[O/V]", "Overview/Victory"),
             ("[?]", "Help"),
             ("[Esc]", "Back"),
         ],
         Screen::ShipDesigner => vec![
             ("[n]", "New Design"),
             ("[j/k]", "Navigate"),
             ("[h/l]", "Component"),
             ("[Enter]", "Confirm"),
             ("[Tab]", "Panel"),
             ("[s]", "Save"),
             ("[d]", "Delete"),
             ("[Esc]", "Back"),
             ("[?]", "Help"),
         ],
         Screen::Settings => vec![
             ("[j/k]", "Navigate"),
             ("[Enter]", "Cycle"),
             ("[Esc]", "Save & Return"),
         ],
     };

     let inner_width = usize::from(area.width.saturating_sub(2)).max(1);
     let mut lines = Vec::new();
     push_wrapped_hint_lines(&mut lines, &hints, inner_width);
     if let Some(context_line) = context {
         lines.push(Line::from(vec![
             Span::styled("Hint: ", Theme::title_style()),
             Span::styled(context_line, Theme::muted_style()),
         ]));
     }

     let paragraph = Paragraph::new(lines)
         .block(Block::default().borders(Borders::TOP))
         .style(Theme::default_style())
         .wrap(Wrap { trim: false });

     frame.render_widget(paragraph, area);
 }

