1. //! Layout helpers
2. 
3. use ratatui::layout::{Constraint, Direction, Layout, Rect};
4. 
5. /// Standard layout with header, main content, and footer
6. pub fn compose_layout(area: Rect) -> (Rect, Rect, Rect) {
7.     let chunks = Layout::default()
8.         .direction(Direction::Vertical)
9.         .constraints([
10.             Constraint::Length(1), // Header
11.             Constraint::Min(10),   // Main content
12.             Constraint::Length(3), // Footer
13.         ])
14.         .split(area);
15. 
16.     (chunks[0], chunks[1], chunks[2])
17. }
18. 
19. /// Split area horizontally with given percentages
20. pub fn split_horizontal(area: Rect, left_percent: u16) -> (Rect, Rect) {
21.     let left_percent = left_percent.min(100);
22.     let chunks = Layout::default()
23.         .direction(Direction::Horizontal)
24.         .constraints([
25.             Constraint::Percentage(left_percent),
26.             Constraint::Percentage(100 - left_percent),
27.         ])
28.         .split(area);
29. 
30.     (chunks[0], chunks[1])
31. }
32. 
33. /// Create a centered popup area
34. pub fn centered_rect(percent_x: u16, percent_y: u16, area: Rect) -> Rect {
35.     let popup_layout = Layout::default()
36.         .direction(Direction::Vertical)
37.         .constraints([
38.             Constraint::Percentage((100 - percent_y) / 2),
39.             Constraint::Percentage(percent_y),
40.             Constraint::Percentage((100 - percent_y) / 2),
41.         ])
42.         .split(area);
43. 
44.     Layout::default()
45.         .direction(Direction::Horizontal)
46.         .constraints([
47.             Constraint::Percentage((100 - percent_x) / 2),
48.             Constraint::Percentage(percent_x),
49.             Constraint::Percentage((100 - percent_x) / 2),
50.         ])
51.         .split(popup_layout[1])[1]
52. }
53. 
54. /// Create a fixed-size centered rect
55. pub fn centered_fixed(width: u16, height: u16, area: Rect) -> Rect {
56.     let x = area.x + (area.width.saturating_sub(width)) / 2;
57.     let y = area.y + (area.height.saturating_sub(height)) / 2;
58.     Rect::new(x, y, width.min(area.width), height.min(area.height))
59. }
60. 
61. #[cfg(test)]
62. mod tests {
63.     use super::*;
64. 
65.     #[test]
66.     fn compose_layout_creates_three_areas() {
67.         let area = Rect::new(0, 0, 80, 24);
68.         let (header, main, footer) = compose_layout(area);
69. 
70.         assert_eq!(header.height, 1);
71.         assert_eq!(footer.height, 3);
72.         assert!(main.height >= 10);
73.     }
74. 
75.     #[test]
76.     fn split_horizontal_respects_percentage() {
77.         let area = Rect::new(0, 0, 100, 24);
78.         let (left, right) = split_horizontal(area, 60);
79. 
80.         assert_eq!(left.width, 60);
81.         assert_eq!(right.width, 40);
82.     }
83. 
84.     #[test]
85.     fn split_horizontal_clamps_over_100() {
86.         let area = Rect::new(0, 0, 100, 24);
87.         // Should not panic or wrap; 100% left means right=0
88.         let (left, right) = split_horizontal(area, 150);
89.         assert_eq!(left.width + right.width, area.width);
90.     }
91. 
92.     #[test]
93.     fn centered_rect_is_centered() {
94.         let area = Rect::new(0, 0, 100, 100);
