702.                         }
703.                     }
704.                 }
705.                 _ => {}
706.             }
707.             return;
708.         }
709. 
710.         if self.state.overlay.show_help {
711.             if KeyMap::is_help(key) || KeyMap::is_escape(key) {
712.                 self.state.overlay.show_help = false;
713.             }
714.             return;
715.         }
716. 
717.         if self.state.overlay.show_palette {
718.             match key.code {
719.                 KeyCode::Esc => {
720.                     self.state.overlay.show_palette = false;
721.                     self.state.overlay.palette_input.clear();
722.                 }
723.                 KeyCode::Enter => {
724.                     let cmd = self.state.overlay.palette_input.clone();
725.                     self.state.overlay.show_palette = false;
726.                     self.state.overlay.palette_input.clear();
727.                     self.execute_palette_input(&cmd);
728.                 }
729.                 KeyCode::Backspace => {
730.                     self.state.overlay.palette_input.pop();
731.                 }
732.                 KeyCode::Char(c) => {
733.                     self.state.overlay.palette_input.push(c);
734.                 }
735.                 _ => {}
736.             }
737.             return;
738.         }
739. 
740.         // Global keys
741.         if KeyMap::is_help(key) {
742.             self.state.overlay.show_help = true;
743.             return;
744.         }
745. 
746.         if KeyMap::is_palette(key) {
747.             self.state.overlay.show_palette = true;
748.             return;
749.         }
750. 
751.         if KeyMap::is_quit(key) {
752.             self.state.quit = true;
753.             return;
754.         }
755. 
756.         if key.code == KeyCode::Char('N') && self.engine.is_some() {
757.             self.open_latest_dispatch();
758.             return;
759.         }
760.         if matches!(key.code, KeyCode::Char('B') | KeyCode::Char('b')) && self.engine.is_some() {
761.             self.open_latest_battle_report();
762.             return;
