228. /// Download the update binary to a staging path next to the current executable.
229. /// The staged file has the current executable's extension replaced with `.update`
230. /// (e.g. `farspace` → `farspace.update`, `farspace.exe` → `farspace.update`).
231. /// It is applied on the next launch.
232. ///
233. /// NOTE: Downloads are protected by TLS only. A future improvement should
234. /// verify a signed manifest or SHA-256 checksum published alongside the release
235. /// asset before staging, to defend against compromised release metadata or a
236. /// network man-in-the-middle attack.
237. pub fn download_and_stage(info: &UpdateInfo) -> anyhow::Result<PathBuf> {
238.     let staging = staged_path()?;
239. 
240.     let agent = ureq::AgentBuilder::new()
241.         .timeout_connect(std::time::Duration::from_secs(10))
242.         .timeout_read(std::time::Duration::from_secs(300))
243.         .build();
244. 
245.     let response = agent
246.         .get(&info.download_url)
247.         .set("User-Agent", &format!("farspace/{CURRENT_VERSION}"))
248.         .call()?;
249. 
250.     let mut reader = response.into_reader();
251.     let mut file = std::fs::File::create(&staging)?;
252.     std::io::copy(&mut reader, &mut file)?;
253. 
254.     // Make executable on Unix
255.     #[cfg(unix)]
256.     {
257.         use std::os::unix::fs::PermissionsExt;
258.         let mut perms = std::fs::metadata(&staging)?.permissions();
259.         perms.set_mode(0o755);
260.         std::fs::set_permissions(&staging, perms)?;
261.     }
262. 
263.     Ok(staging)
264. }
265. 
266. /// Path where the staged update binary is written.
267. pub fn staged_path() -> anyhow::Result<PathBuf> {
268.     let mut path = std::env::current_exe()?;
269.     path.set_extension("update");
270.     Ok(path)
271. }
272. 
273. /// Check for a staged update and apply it before the TUI starts.
274. ///
275. /// On Unix: atomically renames the staged file over the current binary.
276. /// On Windows: copies the staged file over the current binary (best-effort).
277. ///
278. /// Returns `true` if an update was applied (the caller should note that the
279. /// binary on disk has changed, though the running process is the old version).
280. pub fn check_and_apply_staged() -> bool {
281.     let Ok(staged) = staged_path() else {
282.         return false;
283.     };
284.     if !staged.exists() {
285.         return false;
286.     }
287. 
288.     let Ok(current) = std::env::current_exe() else {
289.         let _ = std::fs::remove_file(&staged);
290.         return false;
291.     };
292. 
293.     let applied = apply_staged(&current, &staged);
294.     if applied {
295.         let _ = std::fs::remove_file(&staged);
296.     }
297.     applied
298. }
299. 
300. #[cfg(unix)]
301. fn apply_staged(current: &std::path::Path, staged: &std::path::Path) -> bool {
302.     std::fs::rename(staged, current).is_ok()
303. }
304. 
305. #[cfg(windows)]
306. fn apply_staged(current: &std::path::Path, staged: &std::path::Path) -> bool {
307.     std::fs::copy(staged, current).is_ok()
308. }
309. 
310. #[cfg(not(any(unix, windows)))]
311. fn apply_staged(_current: &std::path::Path, _staged: &std::path::Path) -> bool {
312.     false
313. }
