1. //! Update state types shared between the TUI and the update system in the binary crate.
2. 
3. /// Which release channel the user wants to track.
4. #[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
5. pub enum UpdateChannel {
6.     #[default]
7.     Stable,
8.     /// Alpha/beta prereleases (tags matching `v*-alpha*` or `v*-beta*`).
9.     Preview,
10.     /// Nightly pre-releases (tags matching `nightly-*`).
11.     Nightly,
12. }
13. 
14. impl UpdateChannel {
15.     pub const fn label(self) -> &'static str {
16.         match self {
17.             Self::Stable => "Stable",
18.             Self::Preview => "Preview",
19.             Self::Nightly => "Nightly",
20.         }
21.     }
22. 
23.     pub const fn config_value(self) -> &'static str {
24.         match self {
25.             Self::Stable => "stable",
26.             Self::Preview => "preview",
27.             Self::Nightly => "nightly",
28.         }
29.     }
30. 
31.     pub fn from_config_value(s: &str) -> Option<Self> {
32.         match s.trim().to_ascii_lowercase().as_str() {
33.             "stable" => Some(Self::Stable),
34.             "preview" | "alpha" | "beta" => Some(Self::Preview),
35.             "nightly" => Some(Self::Nightly),
36.             _ => None,
37.         }
38.     }
39. 
40.     pub const fn next(self) -> Self {
41.         match self {
42.             Self::Stable => Self::Preview,
43.             Self::Preview => Self::Nightly,
44.             Self::Nightly => Self::Stable,
45.         }
46.     }
47. }
48. 
49. /// Information about an available release.
50. #[derive(Debug, Clone)]
51. pub struct UpdateInfo {
52.     pub version: String,
53.     pub channel: UpdateChannel,
54.     /// Direct download URL for the binary asset matching the current platform.
55.     pub download_url: String,
56. }
57. 
58. /// State machine for the update lifecycle shown on the menu screen.
59. #[derive(Debug, Clone, Default)]
60. pub enum UpdateState {
61.     /// Nothing to show.
62.     #[default]
63.     Idle,
64.     /// Check running in background.
65.     Checking,
66.     /// Update found and waiting for user action (or auto-download queued).
67.     Available(UpdateInfo),
68.     /// Binary being downloaded.
69.     Downloading,
70.     /// Binary staged on disk; restart needed.
71.     Staged { version: String },
72.     /// User dismissed the notification.
73.     Dismissed,
74.     /// Something went wrong.
75.     Error(String),
76. }
77. 
78. impl UpdateState {
79.     /// Returns true if a notification widget should be shown on the menu screen.
80.     pub fn is_notifiable(&self) -> bool {
81.         matches!(
82.             self,
83.             Self::Available(_) | Self::Downloading | Self::Staged { .. } | Self::Error(_)
84.         )
85.     }
86. }
87. 
